import{_ as a,o as s,c as e,a2 as r}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"选型决策树","description":"","frontmatter":{},"headers":[],"relativePath":"tools/decision-tree.md","filePath":"tools/decision-tree.md","lastUpdated":1785729506000}'),n={name:"tools/decision-tree.md"};function d(o,t,l,i,h,p){return s(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="选型决策树" tabindex="-1">选型决策树 <a class="header-anchor" href="#选型决策树" aria-label="Permalink to &quot;选型决策树&quot;">​</a></h1><p>不讨论&quot;哪个工具最好&quot;——没有这种东西。只回答一个具体问题：<strong>这个项目该配哪套工具。</strong></p><h2 id="第一层-先看交付形态" tabindex="-1">第一层：先看交付形态 <a class="header-anchor" href="#第一层-先看交付形态" aria-label="Permalink to &quot;第一层：先看交付形态&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你要交付什么？</span></span>
<span class="line"><span>├── 静态图（主图 / KV / 海报）      → 走 A 路线</span></span>
<span class="line"><span>├── 短视频（6–30 秒社媒）           → 走 B 路线</span></span>
<span class="line"><span>└── 完整 TVC（30 秒以上，有叙事）   → 走 C 路线</span></span></code></pre></div><hr><h2 id="a-路线-·-静态图" tabindex="-1">A 路线 · 静态图 <a class="header-anchor" href="#a-路线-·-静态图" aria-label="Permalink to &quot;A 路线 · 静态图&quot;">​</a></h2><h3 id="a1-产品必须精确还原吗" tabindex="-1">A1 产品必须精确还原吗？ <a class="header-anchor" href="#a1-产品必须精确还原吗" aria-label="Permalink to &quot;A1 产品必须精确还原吗？&quot;">​</a></h3><p><strong>是</strong>（有 logo、有特定造型、消费者认得出）</p><p>→ <strong>不要纯生成。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>链路：实拍产品图（或官方素材）</span></span>
<span class="line"><span>      → 图像编辑型工具去背 / 换背景</span></span>
<span class="line"><span>      → AI 生成背景与光环境</span></span>
<span class="line"><span>      → 设计软件合成 + 加文字</span></span></code></pre></div><p>工具配置：一个图像编辑型工具 + 一个通用生成型工具 + Photoshop 或同类。</p><p><strong>否</strong>（概念图、氛围图、场景图，产品不出现或不重要）</p><p>→ 纯生成即可，走 A2。</p><h3 id="a2-要几张" tabindex="-1">A2 要几张？ <a class="header-anchor" href="#a2-要几张" aria-label="Permalink to &quot;A2 要几张？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数量</th><th>配置</th></tr></thead><tbody><tr><td>几张</td><td>一个通用生成型工具就够，手动挑选</td></tr><tr><td>几十张（多 SKU / 多尺寸）</td><td>需要<strong>参考控制型</strong>工具锁定风格，否则每张调性都不一样。见 <a href="/cases/case-02-ecommerce-visual">案例 02</a></td></tr></tbody></table><h3 id="a3-海报上有文字吗" tabindex="-1">A3 海报上有文字吗？ <a class="header-anchor" href="#a3-海报上有文字吗" aria-label="Permalink to &quot;A3 海报上有文字吗？&quot;">​</a></h3><p><strong>有</strong> → 文字<strong>一律</strong>在设计软件里加，不要交给生成模型。AI 生成的中文基本是乱码。</p><p>在 Prompt 里主动写负向词 <code>文字、水印</code>，把版面留白留出来。</p><hr><h2 id="b-路线-·-短视频" tabindex="-1">B 路线 · 短视频 <a class="header-anchor" href="#b-路线-·-短视频" aria-label="Permalink to &quot;B 路线 · 短视频&quot;">​</a></h2><h3 id="b1-有没有人物出镜" tabindex="-1">B1 有没有人物出镜？ <a class="header-anchor" href="#b1-有没有人物出镜" aria-label="Permalink to &quot;B1 有没有人物出镜？&quot;">​</a></h3><p><strong>没有</strong>（纯产品、空镜、概念画面）</p><p>→ 最省事的一条路，AI 的成功率最高。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>链路：图像模型生成每个镜头的首帧</span></span>
<span class="line"><span>      → 图生视频让它动起来</span></span>
<span class="line"><span>      → TTS 配音</span></span>
<span class="line"><span>      → 剪辑软件串联 + 调色</span></span></code></pre></div><p><strong>关键</strong>：走<strong>图生视频</strong>而不是文生视频。先把画面调满意再让它动，可控性差一个量级。</p><p><strong>有人物</strong> → 走 B2。</p><h3 id="b2-人物需要说话吗" tabindex="-1">B2 人物需要说话吗？ <a class="header-anchor" href="#b2-人物需要说话吗" aria-label="Permalink to &quot;B2 人物需要说话吗？&quot;">​</a></h3><p><strong>不需要说话</strong>（有表演但用画外音）</p><p>→ 可行。注意用 <a href="/prompts/spokesperson">人物代言</a> 里的规避策略：少用大幅动作，多用侧脸、背影、局部特写。</p><p><strong>需要说话</strong></p><p>→ 口型同步是当前的薄弱环节。三个选项：</p><table tabindex="0"><thead><tr><th>方案</th><th>说明</th></tr></thead><tbody><tr><td><strong>画外音</strong>（推荐）</td><td>人物出画面但不开口，旁白单独配。最稳</td></tr><tr><td>专门的口型同步工具</td><td>效果视工具而定，<strong>必须先试再承诺给客户</strong></td></tr><tr><td>实拍人物 + AI 做其余镜头</td><td>混合生产，质量最有保障，成本也最高</td></tr></tbody></table><h3 id="b3-预算和时间" tabindex="-1">B3 预算和时间 <a class="header-anchor" href="#b3-预算和时间" aria-label="Permalink to &quot;B3 预算和时间&quot;">​</a></h3><table tabindex="0"><thead><tr><th>情况</th><th>建议配置</th></tr></thead><tbody><tr><td><strong>极紧</strong>（当天要，预算很低）</td><td>单一平台走完全链路（国内一体化平台通常图、视频、配音都有），牺牲一些质量换速度</td></tr><tr><td><strong>正常</strong>（三五天）</td><td>每一环选各自最合适的工具，中间手动流转。这是最主流的做法</td></tr><tr><td><strong>充裕</strong>（有排期和预算）</td><td>AI 做前期探索和空镜，关键镜头实拍，走 <a href="/guide/landscape">全景</a> 里的「探索模式」</td></tr></tbody></table><hr><h2 id="c-路线-·-完整-tvc" tabindex="-1">C 路线 · 完整 TVC <a class="header-anchor" href="#c-路线-·-完整-tvc" aria-label="Permalink to &quot;C 路线 · 完整 TVC&quot;">​</a></h2><h3 id="c1-先做一个判断" tabindex="-1">C1 先做一个判断 <a class="header-anchor" href="#c1-先做一个判断" aria-label="Permalink to &quot;C1 先做一个判断&quot;">​</a></h3><p><strong>30 秒以上、有人物表演、有情绪递进的片子，目前不建议纯 AI 生成。</strong></p><p>原因在 <a href="/guide/landscape">AI 创意广告全景</a> 里说过：弱点集中在表演上——表情僵硬、动作不自然、口型对不上。片子越长，这些问题暴露得越充分。</p><h3 id="c2-推荐的混合配置" tabindex="-1">C2 推荐的混合配置 <a class="header-anchor" href="#c2-推荐的混合配置" aria-label="Permalink to &quot;C2 推荐的混合配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>内容类型</th><th>怎么做</th></tr></thead><tbody><tr><td>人物表演镜头</td><td>实拍</td></tr><tr><td>产品特写</td><td>AI 生成或实拍均可，AI 在这里性价比很高</td></tr><tr><td>空镜、环境、氛围</td><td>AI 生成，省下大量外景成本</td></tr><tr><td>超现实 / 概念画面</td><td>AI 生成，这是 AI 优势最大的地方</td></tr><tr><td>分镜预览（故事板）</td><td>AI 生成，成本极低，用来跟客户对齐创意</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一个被低估的用法</p><p>即使最终全部实拍，<strong>用 AI 生成故事板</strong>也很划算：一个下午就能把整支片的每个镜头可视化出来，拿去跟客户对创意。比手绘分镜快，比拍样片便宜几个数量级。这是当前 AI 在高预算项目里最扎实的应用。</p></div><hr><h2 id="第二层-三种预算档的完整配置" tabindex="-1">第二层：三种预算档的完整配置 <a class="header-anchor" href="#第二层-三种预算档的完整配置" aria-label="Permalink to &quot;第二层：三种预算档的完整配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>极低预算</th><th>常规预算</th><th>充裕预算</th></tr></thead><tbody><tr><td><strong>文案策略</strong></td><td>免费大模型</td><td>付费大模型</td><td>付费大模型 + 人工创意</td></tr><tr><td><strong>图像</strong></td><td>一个通用生成工具</td><td>通用 + 编辑型两个工具</td><td>上述 + 实拍产品素材</td></tr><tr><td><strong>视频</strong></td><td>一体化平台</td><td>专门的视频生成工具</td><td>AI + 实拍混合</td></tr><tr><td><strong>配音</strong></td><td>免费 TTS</td><td>付费 TTS</td><td>专业配音演员</td></tr><tr><td><strong>剪辑</strong></td><td>剪映</td><td>专业剪辑软件</td><td>专业剪辑软件 + 调色</td></tr><tr><td><strong>适合</strong></td><td>内部测试、批量投放素材</td><td>绝大多数商业项目</td><td>品牌项目</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">别按预算档硬套</p><p>这张表是起点不是答案。实际项目里，把钱花在<strong>最影响成片质量的那一环</strong>比平均分配有效得多。多数情况下那一环是：<strong>图像/视频生成的重生成次数</strong>，以及<strong>剪辑调色的时间</strong>。</p></div><h2 id="第三层-三个必须先确认的问题" tabindex="-1">第三层：三个必须先确认的问题 <a class="header-anchor" href="#第三层-三个必须先确认的问题" aria-label="Permalink to &quot;第三层：三个必须先确认的问题&quot;">​</a></h2><p>选定工具、开工之前，这三件事没确认清楚，后面可能全部作废：</p><ol><li><strong>商用授权</strong>。你的订阅档位允许把生成内容用于商业广告吗？条款是否覆盖客户的使用范围？**不同产品差异极大，且和订阅档位挂钩。**这是最容易翻车的一项。</li><li><strong>客户对 AI 的态度</strong>。有些甲方明确要求不能用 AI 生成，有些要求必须标注。<strong>开工前问清楚</strong>，别做完了才发现。</li><li><strong>投放平台的规则</strong>。部分平台对 AI 生成内容有标识要求。以平台最新规范为准。</li></ol><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p>静态图看产品要不要精确，视频看有没有人说话，TVC 看要不要表演。 三个问题答完，工具基本就定了。</p></blockquote><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>各类工具的定位 → <a href="/tools/landscape">全景对照表</a></li><li>真实项目里怎么配 → <a href="/cases/">案例拆解</a></li></ul>`,53)])])}const b=a(n,[["render",d]]);export{g as __pageData,b as default};
